INSERT INTO products (
    seller_id
    , name_ko, name_en, name_ja, name_zh
    , category
    , description_ko, description_en
    , price_krw, original_price_krw, discount
    , stock, min_order_quantity, weight_gram, customs_hs_code
    , ingredients_ko, ingredients_en
    , alcohol, volume
    , brewery_ko, brewery_en, brewery_ja, brewery_zh
    , region_ko, region_en
    , heritage_ko, heritage_en
    , tasting_ko, tasting_en, tasting_ja, tasting_zh
    , pairing, pairing_en, bridge_en
) VALUES (
    #{sellerId}
    , #{name}, #{nameEn}, #{nameJa}, #{nameZh}
    , #{category}
    , #{description}, #{descriptionEn}
    , #{price}, #{originalPrice}, IFNULL(#{discount}, 0)
    , #{stock}, IFNULL(#{minOrderQuantity}, 1), #{weightGram}, #{customsHsCode}
    , #{ingredients}, #{ingredientsEn}
    , #{alcoholPercentage}, #{volumeMl}
    , #{brewery}, #{breweryEn}, #{breweryJa}, #{breweryZh}
    , #{region}, #{regionEn}
    , #{heritage}, #{heritageEn}
    , #{tastingKo}, #{tastingEn}, #{tastingJa}, #{tastingZh}
    , #{pairing}, #{pairingEn}, #{bridgeEn}
)

mapper.update:
UPDATE products
SET name_ko            = #{name}
  , name_en            = #{nameEn}
  , name_ja            = #{nameJa}
  , name_zh            = #{nameZh}
  , category           = #{category}
  , description_ko     = #{description}
  , description_en     = #{descriptionEn}
  , price_krw          = #{price}
  , original_price_krw = #{originalPrice}
  , discount           = IFNULL(#{discount}, 0)
  , stock              = #{stock}
  , weight_gram        = #{weightGram}
  , customs_hs_code    = #{customsHsCode}
  , ingredients_ko     = #{ingredients}
  , ingredients_en     = #{ingredientsEn}
  , alcohol            = #{alcoholPercentage}
  , volume             = #{volumeMl}
  , brewery_ko         = #{brewery}
  , brewery_en         = #{breweryEn}
  , brewery_ja         = #{breweryJa}
  , brewery_zh         = #{breweryZh}
  , region_ko          = #{region}
  , region_en          = #{regionEn}
  , heritage_ko        = #{heritage}
  , heritage_en        = #{heritageEn}
  , tasting_ko         = #{tastingKo}
  , tasting_en         = #{tastingEn}
  , tasting_ja         = #{tastingJa}
  , tasting_zh         = #{tastingZh}
  , pairing            = #{pairing}
  , pairing_en         = #{pairingEn}
  , bridge_en          = #{bridgeEn}
  , status             = #{status}
WHERE id = #{id}
  AND deleted_at IS NULL

UPDATE products
SET deleted_at = NOW()
WHERE id = #{id}

UPDATE products
SET stock = stock - #{quantity}
WHERE id = #{productId}
  AND stock >= #{quantity}
  AND deleted_at IS NULL

UPDATE products
SET status = #{status}
WHERE id = #{id}
  AND deleted_at IS NULL
